import {crossingCopy as copy,crossingPrompts,crossingCards,twoCrossingsCopy as twoCopy,twoCrossingsPrompts,twoPanelPrompts,triangleCopy as triCopy,trianglePrompts,trianglePanelPrompts} from './crossing-angles-content.mjs';
import {crossingAnglesModel,crossingAnglesNarration} from './crossing-angles-core.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=v=>Math.round(v*1000)/1000;
const point=(a,r)=>[320+r*Math.cos(a*Math.PI/180),280-r*Math.sin(a*Math.PI/180)];
const xy=p=>p.map(n).join(' ');
const p=(text,cls='')=>`<p${cls?` class="ca-${cls}"`:''}>${esc(text)}</p>`;
const button=(action,label,value='',extra='')=>`<button type="button" data-crossing-angles-action="${action}" data-crossing-angles-value="${esc(value)}" ${extra}>${esc(label)}</button>`;
function marks(s){
 if(s.right){const r=24,a=point(s.start,r),b=point(s.start+s.sweep,r),q=[a[0]+b[0]-320,a[1]+b[1]-280];return `<path class="ca-mark" d="M ${xy(a)} L ${xy(q)} L ${xy(b)}"/>`;}
 return Array.from({length:s.arcCount||1},(_,i)=>{const r=35+i*9;return `<path class="ca-mark" d="M ${xy(point(s.start,r))} A ${r} ${r} 0 ${s.sweep>180?1:0} 0 ${xy(point(s.start+s.sweep,r))}"/>`;}).join('');
}
function stage(g,{title='',inset=''}={}){
 const sectors=g.sectors||[],rays=g.rays||[],id=`crossing-angles-diagram-${inset?`panel-${inset}`:title.replace(/[^a-z0-9]+/gi,'-').toLowerCase()||'explore'}`;
 const labels=[...rays.filter(r=>r.label).map(r=>({name:r.name,position:r.label,target:r.end,ray:true})),...sectors.map(s=>({name:s.name,measure:s.measure,position:s.label,target:s.leader,ray:false}))];
 return `<figure class="ca-figure">${title?`<figcaption class="ca-diagram-title">${esc(title)}</figcaption>`:''}<div class="ca-stage" data-crossing-angles-stage ${inset?`data-crossing-angles-inset="${inset}"`:''}><svg viewBox="0 0 640 560" role="img" aria-labelledby="${id}-title" aria-describedby="${id}-description"><title id="${id}-title">${esc(title||'Two straight lines crossing')}</title><desc id="${id}-description">${esc(g.description||title)}</desc><g class="ca-sectors">${sectors.filter(s=>s.selected).map(s=>`<path d="M 320 280 L ${xy(point(s.start,130))} A 130 130 0 ${s.sweep>180?1:0} 0 ${xy(point(s.start+s.sweep,130))} Z"/>`).join('')}</g><g class="ca-lines">${rays.map(r=>`<line x1="320" y1="280" x2="${n(r.end[0])}" y2="${n(r.end[1])}"/>`).join('')}</g>${sectors.map(marks).join('')}<g class="ca-leaders">${labels.map((l,i)=>`<line data-ca-leader="${i}" x1="${n(l.target[0])}" y1="${n(l.target[1])}" x2="${n(l.position[0])}" y2="${n(l.position[1])}"/>`).join('')}</g><circle cx="320" cy="280" r="5" class="ca-pin"/></svg>${labels.map((l,i)=>`<span class="ca-label ${l.ray?'ca-ray-label':'ca-angle-label'}" data-crossing-angles-label="${esc(l.name)}" data-ca-label="${i}" data-ca-x="${l.position[0]}" data-ca-y="${l.position[1]}" style="left:${l.position[0]/6.4}%;top:${l.position[1]/5.6}%">${esc(l.name)}${l.measure!==undefined?`<strong>${l.measure}°</strong>`:''}</span>`).join('')}<span class="ca-label ca-origin" data-crossing-angles-label="O" style="left:53%;top:54%">O</span></div></figure>`;
}
function twoStage(g){
 const id=`crossing-angles-two-${g.worked?'worked':'explore'}`,line=(r,cls='')=>`<line${cls?` class="${cls}"`:''} x1="${n(r.start[0])}" y1="${n(r.start[1])}" x2="${n(r.end[0])}" y2="${n(r.end[1])}"/>`,at=(c,a,r)=>[c[0]+r*Math.cos(a*Math.PI/180),c[1]-r*Math.sin(a*Math.PI/180)];
 const selected=g.crossings.flatMap(c=>c.sectors.filter(s=>s.selected).map(s=>({...s,center:c.center}))),labels=[...g.crossings.map(c=>({name:c.name,position:[c.center[0]-18,c.center[1]+20],target:c.center,point:true})),...selected.map((s,i)=>({name:s.name,measure:s.measure,position:[i?440:200,i?500:60],target:s.leader}))];
 const arrows=g.rails.filter(r=>r.parallel).map(r=>{const dx=r.end[0]-r.start[0],dy=r.end[1]-r.start[1],len=Math.hypot(dx,dy),u=[dx/len,dy/len],v=[-u[1],u[0]],c=[r.start[0]+dx*.78,r.start[1]+dy*.78];return `<path class="ca-parallel-mark" d="M ${xy([c[0]-u[0]*8+v[0]*7,c[1]-u[1]*8+v[1]*7])} L ${xy(c)} L ${xy([c[0]-u[0]*8-v[0]*7,c[1]-u[1]*8-v[1]*7])}"/>`;}).join('');
 return `<figure class="ca-figure ca-two-figure"><div class="ca-stage ca-two-stage" data-crossing-angles-stage data-crossing-angles-two-stage><svg viewBox="0 0 640 560" role="img" aria-labelledby="${id}-title" aria-describedby="${id}-description"><title id="${id}-title">Two crossings</title><desc id="${id}-description">${esc(g.description)}</desc>${g.rectangle?`<polygon class="ca-panel-boundary" points="${g.rectangle.corners.map(c=>c.map(n).join(',')).join(' ')}"/>`:''}<g class="ca-sectors">${selected.map(s=>`<path data-ca-sector="${s.name}" d="M ${xy(s.center)} L ${xy(at(s.center,s.start,28))} A 28 28 0 ${s.sweep>180?1:0} 0 ${xy(at(s.center,s.start+s.sweep,28))} Z"/>`).join('')}</g><g class="ca-lines">${g.rails.map(r=>line(r)).join('')}${line(g.transversal)}</g>${arrows}<g class="ca-selected-rays">${selected.map(s=>[s.start,s.start+s.sweep].map(a=>line({start:s.center,end:at(s.center,a,28)})).join('')).join('')}</g><g class="ca-tracing">${g.tracing.rays.map(r=>line(r)).join('')}</g><g class="ca-leaders">${labels.map((l,i)=>`<line data-ca-leader="${i}" x1="${n(l.target[0])}" y1="${n(l.target[1])}" x2="${n(l.position[0])}" y2="${n(l.position[1])}"/>`).join('')}</g>${g.crossings.map(c=>`<circle cx="${n(c.center[0])}" cy="${n(c.center[1])}" r="4" class="ca-pin"/>`).join('')}</svg>${labels.map((l,i)=>`<span class="ca-label ${l.point?'ca-point-label':'ca-angle-label'}" data-crossing-angles-label="${l.name}" data-ca-label="${i}" data-ca-x="${l.position[0]}" data-ca-y="${l.position[1]}" style="left:${l.position[0]/6.4}%;top:${l.position[1]/5.6}%">${l.name}${l.measure!==undefined?`<strong>${l.measure}°</strong>`:''}</span>`).join('')}</div></figure>`;
}
function twoReading(g){return `${p(twoCopy.legend,'legend')}${g.context?`${p(g.context.caseTitle)}${p(`${g.context.width} × ${g.context.height}`,'dimensions')}`:''}${p(g.caption)}${p(g.table,'two-table')}${p(g.relation,'selected')}${p(g.tracingCaption)}${g.tracingState?p(g.tracingState):''}`;}
function twoControls(work,g){const panelMode=g.mode==='panel';return `<section class="ca-controls" aria-label="Two crossings controls">${panelMode?p(twoCopy.retained):`<label for="crossing-angles-angle">First angle a</label><select id="crossing-angles-angle" data-crossing-angles-action="angle">${Array.from({length:11},(_,i)=>15+i*15).map(v=>`<option value="${v}"${v===g.angle?' selected':''}>${v}°</option>`).join('')}</select><div class="ca-row">${button('angle','−15°',g.angle-15,`data-crossing-angles-step="less"${g.angle===15?' disabled':''}`)}${button('angle','+15°',g.angle+15,`data-crossing-angles-step="more"${g.angle===165?' disabled':''}`)}</div>${p(twoCopy.sharedAngle)}<label for="crossing-angles-two-spacing">Crossing spacing</label><select id="crossing-angles-two-spacing" data-crossing-angles-action="two-spacing">${[['near','Nearer'],['middle','Middle'],['far','Farther']].map(([v,t])=>`<option value="${v}"${g.spacing===v?' selected':''}>${t}</option>`).join('')}</select><label for="crossing-angles-two-lean">Second line turn</label><select id="crossing-angles-two-lean" data-crossing-angles-action="two-lean">${[[-10,'Lean clockwise 10°'],[0,'Parallel'],[10,'Lean counterclockwise 10°']].map(([v,t])=>`<option value="${v}"${g.lean===v?' selected':''}>${t}</option>`).join('')}</select>${p(twoCopy.leanNote)}`}${button('rotation','Turn the whole picture',(g.rotation+30)%360)}${p(`Picture orientation: ${g.rotation}°`)}${p(twoCopy.sharedRotation)}<div class="ca-row">${[['corresponding','Same position'],['alternate','Inside, opposite sides'],['co-interior','Inside, same side']].map(([v,t])=>button('two-pair',t,v,`aria-pressed="${g.pair===v}"`)).join('')}</div>${p(({corresponding:'Corresponding angles',alternate:'Alternate interior angles','co-interior':'Co-interior angles'})[g.pair])}<div class="ca-row">${button('two-move','Previous tracing position',g.move-1,`data-crossing-angles-tracing="previous"${g.move===0?' disabled':''}`)}${button('two-move','Next tracing position',g.move+1,`data-crossing-angles-tracing="next"${g.move===4?' disabled':''}`)}</div>${p(`Tracing move ${g.move} of 4`)}${g.move===0?p('The tracing starts at O. Four moves take it to P.'):''}<label for="crossing-angles-two-prompt">Choose something to try</label><select id="crossing-angles-two-prompt" data-crossing-angles-action="two-prompt">${(panelMode?twoPanelPrompts:twoCrossingsPrompts).map((c,i)=>`<option value="${i}"${i===work.twoPrompt?' selected':''}>${esc(c.title)}</option>`).join('')}</select><h3>${esc(g.prompt.title)}</h3>${p(g.prompt.text)}</section>`;}
function twoPage(work,m){const g=m.two;return `<section class="ca-two-page"><h2>Two Crossings</h2><div class="ca-row">${[['strips','Free strips'],['panel','My waiting panel']].map(([v,t])=>button('two-mode',t,v,`aria-pressed="${work.twoMode===v}"`)).join('')}</div><div data-crossing-angles-two-region>${g.missing?p(twoCopy.nullContext):`<div class="ca-workbench"><div>${twoStage(g)}${twoReading(g)}</div>${twoControls(work,g)}</div>`}</div></section>`;}
// Triangle marks use their own vertex, never the crossing diagram's origin.
const tn=v=>Math.round(v*1e9)/1e9,txy=p=>p.map(tn).join(' ');
const trianglePoint=(c,a,r)=>[c[0]+r*Math.cos(a*Math.PI/180),c[1]-r*Math.sin(a*Math.PI/180)];
function triangleSector(s,kind){
 const at=a=>trianglePoint(s.center,a,s.radius),start=at(s.start),end=at(s.start+s.sweep);
 const attributes=`data-triangle-sector="${esc(s.name)}" data-triangle-kind="${kind}"`;
 const area=`<path ${attributes} class="ca-triangle-sector ca-triangle-${esc(s.name)}" d="M ${txy(s.center)} L ${txy(start)} A ${tn(s.radius)} ${tn(s.radius)} 0 ${s.sweep>180?1:0} 0 ${txy(end)} Z"/>`;
 if(!s.right)return area;
 const leg=s.radius/Math.sqrt(2),a=trianglePoint(s.center,s.start,leg),b=trianglePoint(s.center,s.start+s.sweep,leg),q=[a[0]+b[0]-s.center[0],a[1]+b[1]-s.center[1]];
 return `<path ${attributes} class="ca-triangle-sector ca-triangle-${esc(s.name)}" d="M ${txy(s.center)} L ${txy(a)} L ${txy(q)} L ${txy(b)} Z"/><path class="ca-mark" data-triangle-right="${esc(s.name)}" d="M ${txy(a)} L ${txy(q)} L ${txy(b)}"/>`;
}
function triangleStage(g){
 const line=(r,kind)=>`<line data-triangle-line="${kind}" x1="${tn(r.start[0])}" y1="${tn(r.start[1])}" x2="${tn(r.end[0])}" y2="${tn(r.end[1])}"/>`;
 const labels=[...g.tags.map(t=>({...t,target:t.leader})),...(g.outline?g.points.map(t=>{const dx=t.point[0]-320,dy=t.point[1]-280,len=Math.hypot(dx,dy)||1;let position=[t.point[0]+dx/len*35,t.point[1]+dy/len*35];
  if(g.view==='outside'&&t.name==='C'){const [a,b,c]=g.vertices,bx=c[0]-b[0],by=c[1]-b[1],length=Math.hypot(bx,by),normal=[-by/length,bx/length],away=normal[0]*(a[0]-c[0])+normal[1]*(a[1]-c[1])>0?-1:1;position=c.map((v,i)=>v+40*away*normal[i]);}
  return {name:t.name,position,target:t.point,point:true};}):[])];
 // Outer labels stay beyond the geometry's 230-unit maximum extent.
 for(const t of labels)if(!t.point){const locations={a:[85,60],b:[555,60],c:[75,500],outside:[555,500]};t.position=locations[t.name]||t.position;}
 return `<figure class="ca-figure ca-triangle-figure"><div class="ca-stage ca-triangle-stage" data-crossing-angles-stage data-crossing-angles-triangle-stage><svg viewBox="0 0 640 560" role="img" aria-labelledby="crossing-angles-triangle-diagram-title" aria-describedby="crossing-angles-triangle-diagram-description"><title id="crossing-angles-triangle-diagram-title">${esc(g.view==='outside'?'Triangle and its adjacent outside corner':g.view==='reason'?'Parallel-line reason for the triangle corners':'Gathering triangle corners')}</title><desc id="crossing-angles-triangle-diagram-description">${esc(`${g.source} ${g.naming} ${g.summary} ${g.counter||''} ${g.text}`)}</desc>${g.interiors.map(s=>triangleSector(s,'interior')).join('')}${g.copies.map(s=>triangleSector(s,s.role)).join('')}${g.outside?triangleSector(g.outside,'outside'):''}<g class="ca-lines">${g.outline?`<polygon data-triangle-outline points="${g.vertices.map(v=>v.map(tn).join(',')).join(' ')}"/>`:''}${g.parallel.map((r,i)=>line(r,`parallel-${i}`)).join('')}${g.extension?line(g.extension,'extension'):''}${g.straight?line(g.straight,'straight'):''}</g>${g.parallel.map(r=>{const dx=r.end[0]-r.start[0],dy=r.end[1]-r.start[1],len=Math.hypot(dx,dy),u=[dx/len,dy/len],v=[-u[1],u[0]],c=[r.start[0]+dx*.8,r.start[1]+dy*.8];return `<path class="ca-parallel-mark" d="M ${txy([c[0]-u[0]*7+v[0]*6,c[1]-u[1]*7+v[1]*6])} L ${txy(c)} L ${txy([c[0]-u[0]*7-v[0]*6,c[1]-u[1]*7-v[1]*6])}"/>`;}).join('')}<g class="ca-leaders">${labels.map((l,i)=>`<line data-ca-leader="${i}" x1="${tn(l.target[0])}" y1="${tn(l.target[1])}" x2="${tn(l.position[0])}" y2="${tn(l.position[1])}"/>`).join('')}</g></svg>${labels.map((l,i)=>`<span class="ca-label ${l.point?'ca-point-label':'ca-angle-label'}" data-crossing-angles-label="${esc(l.name)}" data-ca-label="${i}" data-ca-x="${l.position[0]}" data-ca-y="${l.position[1]}" style="left:${l.position[0]/6.4}%;top:${l.position[1]/5.6}%">${esc(l.name)}</span>`).join('')}</div></figure>`;
}
function triangleControls(work,g){
 const free=g.mode==='free';
 return `<section class="ca-controls" aria-label="Triangle corners controls">${free?['a','b'].map(name=>`<label for="crossing-angles-tri-${name}">Angle ${name} at ${name.toUpperCase()}</label><select id="crossing-angles-tri-${name}" data-crossing-angles-action="tri-${name}">${Array.from({length:10},(_,i)=>15+i*15).map(v=>`<option value="${v}"${v===work[name==='a'?'triA':'triB']?' selected':''}${v+work[name==='a'?'triB':'triA']>165?' disabled':''}>${v}°</option>`).join('')}</select>`).join('')+`<label for="crossing-angles-tri-size">Drawing size</label><select id="crossing-angles-tri-size" data-crossing-angles-action="tri-size">${[['small','Small'],['large','Large']].map(([v,t])=>`<option value="${v}"${work.triSize===v?' selected':''}>${t}</option>`).join('')}</select>`:p('Your free triangle settings are waiting. This triangle uses half of your copied rectangle.')}${button('rotation','Turn the whole picture',(g.rotation+30)%360)}${p(`Picture orientation: ${g.rotation}°`)}${p(triCopy.rotationNote)}<label for="crossing-angles-tri-prompt">Choose something to try</label><select id="crossing-angles-tri-prompt" data-crossing-angles-action="tri-prompt">${(free?trianglePrompts:trianglePanelPrompts).map((c,i)=>`<option value="${i}"${i===work.triPrompt?' selected':''}>${esc(c.title)}</option>`).join('')}</select><h3>${esc(g.prompt.title)}</h3>${p(g.prompt.text)}</section>`;
}
function triangleSteps(g){const stepAction=g.view==='gather'?'tri-gather':'tri-proof';return `${g.view==='outside'?'':`<div class="ca-row">${button(stepAction,g.view==='gather'?'Previous move':'Previous reason',g.step-1,`data-crossing-angles-tri-step="previous"${g.step===0?' disabled':''}`)}${button(stepAction,g.view==='gather'?'Next move':'Next reason',g.step+1,`data-crossing-angles-tri-step="next"${g.step===2?' disabled':''}`)}</div>`}${g.counter?p(g.counter,'triangle-counter'):''}`;}
function trianglePage(work,m){const g=m.triangle;return `<section class="ca-triangle-page"><h2>Triangle corners</h2><div class="ca-row">${[['free','Free triangle'],['panel','My waiting panel']].map(([v,t])=>button('tri-mode',t,v,`aria-pressed="${work.triMode===v}"`)).join('')}</div><div class="ca-row">${[['gather','Gather corners'],['reason','Why every triangle?'],['outside','Outside corner']].map(([v,t])=>button('tri-view',t,v,`aria-pressed="${work.triView===v}"`)).join('')}</div><div data-crossing-angles-triangle-region>${g.missing?p(triCopy.nullContext):`<div class="ca-workbench"><div>${triangleSteps(g)}${triangleStage(g)}${p(g.text)}${g.equations.length?`<div class="ca-triangle-equations">${g.equations.map(e=>p(e,'equation')).join('')}</div>`:''}${p(g.source)}${g.context?p(`${g.context.width} × ${g.context.height}`,'dimensions'):''}${p(g.definition)}${p(g.naming)}${p(g.summary,'triangle-summary')}${g.workedExample?`<aside class="ca-triangle-example"><h3>Separate worked example</h3>${p(g.workedExample)}</aside>`:''}</div>${triangleControls(work,g)}</div>`}</div></section>`;}
function measures(g){return `<div class="ca-measures">${g.sectors.map(s=>p(`${s.name}: ${s.measure}°`)).join('')}</div>${p('AOB + BOC = 180°','equation')}${p('All four angles: 360°')}`;}
function build(work,m){const b=m.build,g=m.geometry;return `<div class="ca-workbench"><div>${stage(g)}${p(copy.arcLegend,'legend')}${measures(g)}</div><section class="ca-controls" aria-label="Explore controls"><label for="crossing-angles-angle">Angle AOB</label><select id="crossing-angles-angle" data-crossing-angles-action="angle">${Array.from({length:11},(_,i)=>15+i*15).map(v=>`<option value="${v}"${v===b.angle?' selected':''}>${v}°</option>`).join('')}</select><div class="ca-row">${button('angle','−15°',b.angle-15,`data-crossing-angles-step="less"${b.canLess?'':' disabled'}`)}${button('angle','+15°',b.angle+15,`data-crossing-angles-step="more"${b.canMore?'':' disabled'}`)}</div>${button('rotation','Turn the whole picture',(b.rotation+30)%360)}${p(`Picture orientation: ${b.rotation}°`)}<div class="ca-row">${['opposite','adjacent'].map(v=>button('pair',v==='opposite'?'Opposite pair':'Adjacent pair',v,`aria-pressed="${b.pair===v}"`)).join('')}</div>${p(g.selectedNames.map(name=>`${name}: ${g.sectors.find(s=>s.name===name).measure}°`).join(' · '),'selected')}<label for="crossing-angles-prompt">Choose something to try</label><select id="crossing-angles-prompt" data-crossing-angles-action="prompt">${crossingPrompts.map((c,i)=>`<option value="${i}"${i===work.prompt?' selected':''}>${esc(c.title)}</option>`).join('')}</select><h3>${esc(m.prompt.title)}</h3>${p(m.prompt.text)}</section></div>`;}
function panel(frame){const rect=frame.rectangle,corners=rect.corners,sub=frame.subscript, index=sub==='₁'?1:2;return `<section class="ca-panel" data-crossing-angles-panel="${index}"><h4>${esc(frame.title)}</h4>${p(`${frame.width} × ${frame.height}`,'dimensions')}<div class="ca-rectangle"><svg viewBox="0 0 240 240" role="img" aria-label="${esc(`${frame.title}, rectangle ${frame.width} by ${frame.height}. Four outside corners are right angles; both diagonals join opposite corners.`)}"><g transform="translate(-200 -160)"><polygon points="${corners.map(c=>c.map(n).join(',')).join(' ')}"/>${[[0,2],[1,3]].map(([a,b])=>`<line x1="${corners[a][0]}" y1="${corners[a][1]}" x2="${corners[b][0]}" y2="${corners[b][1]}"/>`).join('')}${corners.map(c=>{const dx=c[0]<320?1:-1,dy=c[1]<280?1:-1,s=Math.min(8,rect.width/4,rect.height/4);return `<path d="M ${c[0]+dx*s} ${c[1]} v ${dy*s} h ${-dx*s}"/>`;}).join('')}${frame.square?'<path d="M 326 274 L 320 268 L 314 274"/>':''}</g></svg></div><div class="ca-dimension-captions"><span class="ca-dimension">Width: ${frame.width}</span><span class="ca-dimension">Height: ${frame.height}</span></div>${stage({...frame.inset,description:frame.description},{title:'Crossing enlarged: same angles',inset:index})}</section>`;}
function learn(work,m){const card=crossingCards[work.card];let visual='',reading='';
 if(work.card>=4){const g=m.two,step=card.steps?.[work.step];visual=twoStage(g)+p(twoCopy.workedCaption)+twoReading(g);reading=step?p(step.text)+step.equations.map(e=>p(e,'equation')).join('')+`<div class="ca-row">${button('step','Previous reason',work.step-1,`data-crossing-angles-reason="previous"${work.step===0?' disabled':''}`)}${button('step','Next reason',work.step+1,`data-crossing-angles-reason="next"${work.step===2?' disabled':''}`)}</div>`:p(card.text)+(card.equations||[]).map(e=>p(e,'equation')).join('');}
 else if(work.card===3){if(!m.context)return `<section class="ca-teaching"><label for="crossing-angles-card">Choose an explanation</label>${cardSelect(work)}<h3>${esc(card.title)}</h3>${p(copy.nullContext)}</section>`;
 visual=`${p('My waiting Copy Frame panel','waiting-label')}${p(m.context.caseTitle)}${p(copy.panelNote)}<div class="ca-panels">${m.context.frames.map(panel).join('')}</div>`;
 reading=p(card.text)+p(copy.panelWaitingNote)+p(copy.subscriptNote)+p(m.context.statement)+p(copy.arcLegend,'legend');
 }else{visual=m.diagrams.map(d=>stage(d.geometry,{title:d.title})).join('');if(work.card===1){const step=card.steps[work.step];reading=`${p(step.text)}${step.equations.map(e=>p(e,'equation')).join('')}<div class="ca-row">${button('step','Previous reason',work.step-1,`data-crossing-angles-reason="previous"${work.step===0?' disabled':''}`)}${button('step','Next reason',work.step+1,`data-crossing-angles-reason="next"${work.step===2?' disabled':''}`)}</div>`;}else reading=p(card.text);}
 return `<section class="ca-teaching"><label for="crossing-angles-card">Choose an explanation</label>${cardSelect(work)}<h3 id="crossing-angles-card-title">${esc(card.title)}</h3><div class="${work.card===3?'ca-panel-lesson':'ca-workbench'}"><div>${visual}</div><div class="ca-reading">${reading}${work.card<3?p(copy.arcLegend,'legend'):''}</div></div></section>`;
}
function cardSelect(work){return `<select id="crossing-angles-card" data-crossing-angles-action="card">${crossingCards.map((c,i)=>`<option value="${i}"${i===work.card?' selected':''}>${esc(c.title)}</option>`).join('')}</select>`;}
export function renderCrossingAngles(work,context=null){const m=crossingAnglesModel(work,context),two=work.page==='parallel'||work.page==='learn'&&work.card>=4,tri=work.page==='triangle';return `<section class="crossing-angles-root" data-crossing-angles-root><header class="ca-header"><div><h1 id="crossing-angles-title" tabindex="-1">${esc(copy.title)}</h1>${p(tri?triCopy.instruction:two?(work.page==='parallel'?twoCopy.instruction:twoCopy.header):copy.instruction)}</div>${button('back','Back to Copy Frame')}</header><nav class="ca-row" aria-label="Crossing Angles pages">${[['build','Explore'],['learn','See why'],['parallel','Two crossings'],['triangle','Triangle corners']].map(([v,t])=>button('page',t,v,`aria-pressed="${work.page===v}"`)).join('')}</nav><button type="button" data-crossing-angles-hear data-speak="${esc(crossingAnglesNarration(work,context))}" data-speak-lang="en">Hear this page</button>${p(tri?triCopy.modelNote:two?twoCopy.modelNote:copy.modelNote,'model-note')}${tri?trianglePage(work,m):work.page==='build'?build(work,m):work.page==='parallel'?twoPage(work,m):learn(work,m)}${two||tri?'':p(copy.straightTurn)}${p(copy.lifetime,'lifetime')}<details class="ca-adult"><summary>For grown-ups</summary>${p(copy.adultNote)}${p(twoCopy.adultNote)}${p(triCopy.adultNote)}</details></section>`;}
// Labels keep their real text size on phones. Resolve the concrete narrow-ray
// collisions using measured HTML boxes, then move their decorative leaders.
function arrange(stage){
 const w=stage.clientWidth,h=stage.clientHeight;if(!w||!h)return;
 const labels=[...stage.querySelectorAll('[data-ca-label]')].map(node=>({node,x:Number(node.dataset.caX)*w/640,y:Number(node.dataset.caY)*h/560,tx:Number(node.dataset.caX)*w/640,ty:Number(node.dataset.caY)*h/560,hw:node.offsetWidth/2+3,hh:node.offsetHeight/2+3}));
 for(let k=0;k<160;k++){let overlap=false;for(const a of labels){a.x=Math.max(a.hw,Math.min(w-a.hw,a.x));a.y=Math.max(a.hh,Math.min(h-a.hh,a.y));}for(let i=0;i<labels.length;i++)for(let j=i+1;j<labels.length;j++){const a=labels[i],b=labels[j],dx=a.x-b.x,dy=a.y-b.y,ox=a.hw+b.hw-Math.abs(dx),oy=a.hh+b.hh-Math.abs(dy);if(ox>0&&oy>0){overlap=true;if(ox<oy){const s=dx===0?(i%2?1:-1):Math.sign(dx);a.x+=s*(ox/2+.2);b.x-=s*(ox/2+.2);}else{const s=dy===0?(i%2?1:-1):Math.sign(dy);a.y+=s*(oy/2+.2);b.y-=s*(oy/2+.2);}}}if(!overlap)break;}
 for(const a of labels){a.node.style.left=`${a.x/w*100}%`;a.node.style.top=`${a.y/h*100}%`;const line=stage.querySelector(`[data-ca-leader="${a.node.dataset.caLabel}"]`);line?.setAttribute('x2',n(a.x/w*640));line?.setAttribute('y2',n(a.y/h*560));}
}
export function bindCrossingAngles(work,context,ctx){
 const root=document.querySelector('[data-crossing-angles-root]');if(!root)return;
 const live=node=>root.isConnected&&root.contains(node)&&document.querySelector('[data-crossing-angles-root]')===root&&ctx.live(node);
 const stop=()=>{ctx.stopSpeech();ctx.stopSound();};
 for(const node of root.querySelectorAll('button,select,summary')){const guard=e=>{if(node.disabled||!live(node)){e.preventDefault();e.stopImmediatePropagation();}};for(const type of ['click','input','change'])node.addEventListener(type,guard,{capture:true});}
 const hear=root.querySelector('[data-crossing-angles-hear]');hear.addEventListener('click',()=>{if(live(hear))hear.dataset.speak=crossingAnglesNarration(work,context);},{capture:true});
 for(const node of root.querySelectorAll('[data-crossing-angles-action]'))node.addEventListener(node.tagName==='SELECT'?'change':'click',()=>{if(!live(node)||node.disabled)return;const action=node.dataset.crossingAnglesAction;if(action==='back'){stop();ctx.back();return;}const raw=node.tagName==='SELECT'?node.value:node.dataset.crossingAnglesValue,value=['angle','rotation','prompt','card','step','two-lean','two-move','two-prompt','tri-a','tri-b','tri-gather','tri-proof','tri-prompt'].includes(action)?Number(raw):raw;stop();if(!ctx.change(action,value)){if(node.tagName==='SELECT'){const keys={'angle':'angle','rotation':'rotation','prompt':'prompt','card':'card','two-spacing':'twoSpacing','two-lean':'twoLean','two-prompt':'twoPrompt','tri-a':'triA','tri-b':'triB','tri-size':'triSize','tri-prompt':'triPrompt'};if(keys[action])node.value=String(work[keys[action]]);}return;}ctx.render();let selector=`[data-crossing-angles-action="${action}"]`;if(node.tagName==='SELECT')selector=`#${node.id}`;else if(action==='angle'){const direction=node.dataset.crossingAnglesStep;selector=`[data-crossing-angles-step="${value===15?'more':value===165?'less':direction}"]`;}else if(action==='step')selector=`[data-crossing-angles-reason="${value===0?'next':value===2?'previous':node.dataset.crossingAnglesReason}"]`;else if(action==='two-move')selector=`[data-crossing-angles-tracing="${value===0?'next':value===4?'previous':node.dataset.crossingAnglesTracing}"]`;else if(['tri-gather','tri-proof'].includes(action))selector=`[data-crossing-angles-tri-step="${value===0?'next':value===2?'previous':node.dataset.crossingAnglesTriStep}"]`;else if(['pair','page','two-mode','two-pair','tri-mode','tri-view'].includes(action))selector+=`[data-crossing-angles-value="${esc(value)}"]`;ctx.focus(selector);});
 for(const stage of root.querySelectorAll('[data-crossing-angles-stage]')){arrange(stage);const observer=new ResizeObserver(()=>{if(root.isConnected&&root.contains(stage)&&document.querySelector('[data-crossing-angles-root]')===root)arrange(stage);else observer.disconnect();});observer.observe(stage);}
}
